using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AstralReboundEffect", menuName = "Data/Battle/Effects/Player/AstralRebound Effect")]
public class AstralReboundEffect : Effect
{
	[NonSerialized]
	private bool astralReboundJustApplied;

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance.DiceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			astralReboundJustApplied = true;
		}
	}

	public bool CheckAstralReboundJustApplied()
	{
		if (astralReboundJustApplied)
		{
			astralReboundJustApplied = false;
			return true;
		}
		return false;
	}
}
